// Fasst alle geladenen Produktseiten zu einer flachen Liste von Produkten zusammen
const TAG_NAME = 'sale';
const alleProdukte = [];

for (const item of $input.all()) {
  const body = item.json;
  const edges = body?.data?.products?.edges || [];
  for (const edge of edges) {
    alleProdukte.push(edge.node);
  }
}

function variantIstReduziert(v) {
  const price = parseFloat(v.price);
  const compareAt = v.compareAtPrice !== null && v.compareAtPrice !== undefined && v.compareAtPrice !== ''
    ? parseFloat(v.compareAtPrice)
    : null;

  if (compareAt === null || isNaN(compareAt) || isNaN(price)) return false;

  return compareAt > 0 && compareAt !== price;
}

const ergebnisse = [];

for (const product of alleProdukte) {
  const variants = (product.variants?.edges || []).map(e => e.node);
  const hatReduzierteVariante = variants.some(variantIstReduziert);

  const currentTags = (product.tags || []);
  const hatTagBereits = currentTags.includes(TAG_NAME);

  const needsTagAdd = hatReduzierteVariante && !hatTagBereits;
  const needsTagRemove = !hatReduzierteVariante && hatTagBereits;

  if (needsTagAdd || needsTagRemove) {
    ergebnisse.push({
      json: {
        productId: product.id,
        productGid: product.id,
        title: product.title,
        tagName: TAG_NAME,
        hatReduzierteVariante,
        hatTagBereits,
        needsTagAdd,
        needsTagRemove
      }
    });
  }
}

return ergebnisse;

const names = $('Einstellungen').first().json;
const merchName = names.merchName;
const saleName = names.collectionName;
const targetName = names.targetName;
const goodiesName = names.goodiesName;

const map = {};
for (const it of $('Alle Collections laden').all()) {
  const edges = it.json?.data?.collections?.edges || [];
  for (const e of edges) map[e.node.title] = e.node.id;
}

const merchId = map[merchName] || null;
const saleId = map[saleName] || null;
const targetId = map[targetName] || null;
const goodiesId = map[goodiesName] || null;

const fehlend = [];
if (!merchId) fehlend.push(merchName);
if (!saleId) fehlend.push(saleName);
if (!targetId) fehlend.push(targetName);
if (!goodiesId) fehlend.push(goodiesName);
if (fehlend.length) {
  throw new Error('Collection(s) nicht gefunden: ' + fehlend.join(', '));
}

return [{ json: { merchId, saleId, targetId,goodiesId } }];

function sammle(nodeName) {
  const s = new Set();
  for (const it of $(nodeName).all()) {
    const edges = it.json?.data?.collection?.products?.edges || [];
    for (const e of edges) s.add(e.node.id);
  }
  return s;
}

const merch = sammle('Merch-Produkte laden');
const goodies = sammle('Goodies-Produkte laden');
const sale = sammle('Sale-Produkte laden');
const ziel = sammle('Ziel-Produkte laden');

// Basis = Merch UND Rabattcode Goodies zusammengeführt
const basis = new Set([...merch, ...goodies]);

// Hinzufügen: in Basis (Merch+Goodies), NICHT in Sale, noch nicht im Ziel
const hinzu = [...basis].filter(id => !sale.has(id) && !ziel.has(id));
// Entfernen: aktuell im Ziel UND in Sale (unverändert wie bisher)
const entfernen = [...ziel].filter(id => sale.has(id));

function chunk(arr, n) { const r = []; for (let i = 0; i < arr.length; i += n) r.push(arr.slice(i, i + n)); return r; }

const out = [];
for (const c of chunk(hinzu, 100)) out.push({ json: { action: 'add', productIds: c, anzahl: c.length } });
for (const c of chunk(entfernen, 100)) out.push({ json: { action: 'remove', productIds: c, anzahl: c.length } });

return out;

